head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDBNS21100.xml";
scwin.processGp;
scwin.vRowCount = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 설명       : 보증기관관리 조회
 ***********************************************/
scwin.fn_list_search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LIST";
    url += "&queryId=lds.stf.bnsinst.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_COM_NM=" + txb_com_abbrv.getValue(); // 
    url += "&{P}V_INST_STAT_CD=" + $c.stf.getObjectValue(cmb_sch_inst_stat_cd); // 

    dts_List_1.DataID = encodeURI(url);
    dts_List_1.Reset();
    $c.cm.ShowWin(grd_List);
    return url;
};


/********************************************** 
 * 설명       : 보증기관관리 상세조회
 ***********************************************/
scwin.fn_searchDetail = function(row) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LISTDETAIL";
    url += "&queryId=lds.stf.bnsinst.select.listdetail";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + dts_List_1.getCellData(row, "BND_INST_CD"); // 			

    dts_List_2.DataID = encodeURI(url);
    dts_List_2.Reset();
    btn_reset.setDisabled(false);
    btn_reset.src = "../img/bns/btn_new_n.gif";
    btn_insert.setDisabled(true);
    btn_insert.src = "../img/bns/btn_40_d.gif";
    btn_update.setDisabled(false);
    btn_update.src = "../img/bns/btn_modify_n.gif";
    return url;
};



/********************************************** 
 * 설명       : 보증기관관리 코드존재여부 체크
 ***********************************************/
scwin.fn_chkInstCd = function(vsInstCd) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LISTDETAIL";
    url += "&queryId=lds.stf.bnsinst.select.listdetail";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + $c.stf.getObjectValue(edt_inst_cd); // 			

    dts_ChkCd.DataID = encodeURI(url);
    dts_ChkCd.Reset();
    if (dts_ChkCd.getCellData(0, "BND_INST_CD") == null) {
        return false;
    } else {
        return true;
    }
};




/********************************************** 
 * 설명       : 보증기관등록 
 ***********************************************/
scwin.fn_Insert = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "신규등록"))) return;
    if (scwin.fn_chkInstCd()) {
        $c.win.alert("[" + dts_ChkCd.getCellData(0, "BND_INST_CD") + "]기관코드는 [" + dts_ChkCd.getCellData(0, "INST_NM") + "]에서 사용중입니다.");
        return;
    }
    dts_List_2.setCellData(1, "ZIP_CD", dts_List_2.getCellData(1, "ZIP_CD").replace("-", ""));
    var url = "/bns/Inst.do?method=insertInst";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_save.Action = $c.lc.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};


/********************************************** 
 * 설명       : 보증기관 수정
 ***********************************************/
scwin.fn_Update = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    dts_List_2.setCellData(1, "ZIP_CD", dts_List_2.getCellData(1, "ZIP_CD").replace("-", ""));
    var url = "/bns/Inst.do?method=updateInst";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_save.Action = $c.lc.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};


/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(txb_isur_cd),
        INST_NM: $c.stf.getObjectValue(txb_com_abbrv),
        LBL_NM: '',
        INIT_TP_CD: "2"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) != 'undefined') {
        txb_isur_cd.setValue(arrPar[0].INST_CD);
        txb_com_abbrv.setValue(arrPar[0].INST_NM);
    }
};




/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 우편번호
 ***********************************************/
scwin.fn_SetZipCode = function(arrPar) {
    $c.stf.setObjectValue(edt_zip_cd, arrPar[0]);
    txb_addr.setValue(arrPar[1]);
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);
    $c.bns.BnsPanelToGroupBox(panel_2);
    //데이터셋 초기화
    dts_List_1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_LIST";
    dts_List_1.reset();
    dts_List_2.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_LISTDETAIL";
    dts_List_2.reset();
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_Cntrcd, '01371'); //국가 01371
    //공통콤보
    var arrCid = [];
    //arrCid.push({cid:'02025', cnm:'cmb_cnrt_cd'});//국가				
    arrCid.push({
        cid: '03473',
        cnm: 'cmb_inst_stat_cd'
    }); //기관상태			
    $c.bns.fn_SetBnsComboToCode(scwin.vScrenID, dts_Temp, arrCid);

    // 버튼 세팅
    btn_reset.setDisabled(false);
    btn_reset.src = "../img/bns/btn_new_n.gif";
    btn_insert.setDisabled(true);
    btn_insert.src = "../img/bns/btn_40_d.gif";
    btn_update.setDisabled(true);
    btn_update.src = "../img/bns/btn_modify_nd.gif";
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * Event   : btn_Search > OnClick
     * 설명    : 조회버튼 클릭
     ***********************************************/
    // 조회
    scwin.fn_list_search();
};
scwin.img_com_srch_onclick = function() {
    /********************************************** 
     * Event   : img_com_srch > OnClick
     * 설명    : 발행기관 조회팝업
     ***********************************************/
    fn_GetPar = fn_GetParInst;
    fn_SetPar = fn_SetParInst;
    $c.bns.fn_PopInstSearch(img_com_srch);
};
scwin.txb_isur_cd_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISUR_CD > onblur
     * 설명      : 발행기관 코드 변경
     ***********************************************/
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.btn_reset_onclick = function() {
    /********************************************** 
     * Event   : btn_reset > OnClick
     * 설명    : 초기버튼 클릭
     ***********************************************/
    dts_List_2.removeAll();
    dts_List_2.insertRow();
    edt_inst_cd.setDisabled(false);
    cmb_cnrt_cd.indes = 0;
    cmb_inst_stat_cd.setSelectedIndex(0);
    btn_reset.setDisabled(true);
    btn_reset.src = "../img/bns/btn_new_nd.gif";
    btn_insert.setDisabled(false);
    btn_insert.src = "../img/bns/btn_40.gif";
    btn_update.setDisabled(true);
    btn_update.src = "../img/bns/btn_modify_nd.gif";
};
scwin.btn_insert_onclick = function() {
    /********************************************** 
     * Event   : btn_insert > OnClick
     * 설명    : 신규버튼 클릭
     ***********************************************/
    scwin.processGp = SCREN_PROCS_TP_CD_02;
    if ($c.stf.getObjectValue(edt_inst_cd) == "") {
        $c.win.alert("기관코드를 입력하세요");
        return false;
    }

    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_inst_nm, 25, '한글기관명')) return false;
    if (!$c.stf.checkMaxLength(txb_inst_srt_nm, 20, '한글기관약명')) return false;
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_inst_eng_nm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기관명에 한글은 사용할 수 없습니다');
            txb_inst_eng_nm.focus();
            return false;
        }
    }
    var str = $c.stf.getObjectValue(txb_inst_eng_srt_nm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기관약명에 한글은 사용할 수 없습니다');
            txb_inst_eng_srt_nm.focus();
            return false;
        }
    }

    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_addr, 200, '주소')) return false;
    if (!$c.stf.checkMaxLength(txb_dong_addr, 200, '동이하주소')) return false;
    if (!$c.stf.checkMaxLength(txb_inst_kind_contn, 20, '기관종류')) return false;
    scwin.fn_Insert();
};
scwin.btn_update_onclick = function() {
    /********************************************** 
     * Event   : btn_update > OnClick
     * 설명    : 수정버튼 클릭
     ***********************************************/
    scwin.processGp = SCREN_PROCS_TP_CD_03;
    scwin.fn_Update();
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.dts_List_1_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_1 > OnLoadError
     * 설명    : dts_List_1 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List_1 > OnLoadCompleted
     * 설명    : dts_List_1 조회성공시 처리
     ***********************************************/
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount > 0) {
        btn_reset.setDisabled(false);
        btn_reset.src = "../img/bns/btn_new_n.gif";
        btn_insert.setDisabled(true);
        btn_insert.src = "../img/bns/btn_40d.gif";
        btn_update.setDisabled(false);
        btn_update.src = "../img/bns/btn_modify_n.gif";
    } else {
        btn_reset.setDisabled(false);
        btn_reset.src = "../img/bns/btn_new_n.gif";
        btn_insert.setDisabled(true);
        btn_insert.src = "../img/bns/btn_40_d.gif";
        btn_update.setDisabled(true);
        btn_update.src = "../img/bns/btn_modify_nd.gif";
    }
};
scwin.dts_List_2_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadError
     * 설명    : dts_List_2 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadCompleted
     * 설명    : dts_List_2 조회성공시 처리
     ***********************************************/
    edt_inst_cd.setDisabled(true);
};
scwin.dts_ChkCd_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_ChkCd > OnLoadError
     * 설명    : dts_ChkCd 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_ChkCd_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_ChkCd > OnLoadCompleted
     * 설명    : dts_ChkCd 조회성공시 처리
     ***********************************************/
};
scwin.trs_save_OnFail = function() {
    /********************************************** 
     * Event   : trs_save > OnFail
     * 설명    : 저장 에러시 처리
     ***********************************************/
    if (scwin.processGp == SCREN_PROCS_TP_CD_02) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "신규등록"));
    }
    if (scwin.processGp == SCREN_PROCS_TP_CD_03) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == SCREN_PROCS_TP_CD_04) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
};
scwin.trs_save_OnSuccess = function() {
    /********************************************** 
     * Event   : trs_save > OnSuccess
     * 설명    : 저장 성공시 처리
     ***********************************************/
    // 버튼 세팅
    btn_reset.setDisabled(true);
    btn_reset.src = "../img/bns/btn_new_nd.gif";
    btn_insert.setDisabled(true);
    btn_insert.src = "../img/bns/btn_40_d.gif";
    btn_update.setDisabled(false);
    btn_update.src = "../img/bns/btn_modify_n.gif";

    //메세지처리
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    // 조회
    scwin.fn_list_search();
};
scwin.dts_List_1_OnRowPosChanged = function(row) {
    /********************************************** 
     * Event   : dts_List_1 > OnRowPosChanged
     * 설명    : 그리드 위치 변경시 세팅
     ***********************************************/
    scwin.fn_searchDetail(row);
};
scwin.btn_zip_search_onclick = function() {
    /********************************************** 
     * Event   : btn_zip_search > onclick
     * 설명    : 우편번호 검색
     ***********************************************/
    fn_SetPar = fn_SetZipCode;
    $c.lc.fn_PopFindZipCd();
};
